33	 * Also it prevents writing an arbitrary values to the respective fields, keeping consistency on runtime
34	 * AuthenticatedUser.
35	 *
36	 * @see AuthenticatedUser
37	 */
38	public class JsAuthenticatedUser extends AbstractJSObjectWrapper<AuthenticatedUser> {
39	
40	    public JsAuthenticatedUser(AuthenticatedUser wrapped) {
41	        super(wrapped);
42	    }
43	
44	    @Override
45	    public Object getMember(String name) {
46	
47	        switch (name) {
48	            case FrameworkConstants.JSAttributes.JS_AUTHENTICATED_SUBJECT_IDENTIFIER:
49	                return getWrapped().getAuthenticatedSubjectIdentifier();
50	            case FrameworkConstants.JSAttributes.JS_USERNAME:
51	                return getWrapped().getUserName();
52	            case FrameworkConstants.JSAttributes.JS_USER_STORE_DOMAIN:
53	                return getWrapped().getUserStoreDomain();
54	            case FrameworkConstants.JSAttributes.JS_TENANT_DOMAIN:
55	                return getWrapped().getTenantDomain();
56	            default:
57	                return super.getMember(name);
58	        }
59	    }
60	
61	    @Override
62	    public boolean hasMember(String name) {
63	
64	        switch (name) {
65	            case FrameworkConstants.JSAttributes.JS_AUTHENTICATED_SUBJECT_IDENTIFIER:
66	                return getWrapped().getAuthenticatedSubjectIdentifier() != null;
67	            case FrameworkConstants.JSAttributes.JS_USERNAME:
68	                return getWrapped().getUserName() != null;
69	            case FrameworkConstants.JSAttributes.JS_USER_STORE_DOMAIN:
70	                return getWrapped().getUserStoreDomain() != null;
71	            case FrameworkConstants.JSAttributes.JS_TENANT_DOMAIN:
72	                return getWrapped().getTenantDomain() != null;
73	            default:
74	                return super.hasMember(name);
75	        }
76	    }
77	}
