37	
38	        if (values != null) {
39	            if (values.length <= 0) {
40	                logger.debug("");
41	            } else if (values.length == 1) {
42	                logger.debug(String.valueOf(values[0]));
43	            } else {
44	                StringBuilder stringBuilder = new StringBuilder();
45	                for (Object value : values) {
46	                    stringBuilder.append(String.valueOf(value));
47	                    stringBuilder.append(" ");
48	                }
49	                logger.debug(stringBuilder.toString());
50	            }
51	        }
52	    }
53	
