121	                claimMapping.setRequested(Boolean.parseBoolean(element.getText()));
122	            }
123	
124	            if ("MandatoryClaim".equals(elementName)) {
125	                claimMapping.setMandatory(Boolean.parseBoolean(element.getText()));
126	            }
