public class JsClaimView extends AbstractJSObjectWrapper<Map<ClaimMapping, String>> {

    private final IdMapper idMapper;

    public JsClaimView(Map<ClaimMapping, String> wrapped, IdMapper idMapper) {

        super(wrapped);
        this.idMapper = idMapper;
    }

    @Override
    public Object getMember(String name) {

        for (Map.Entry<ClaimMapping, String> entry : getWrapped().entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                return entry.getValue();
            }
        }
        return null;
    }

    @Override
    public void setMember(String name, Object value) {

        for (Map.Entry<ClaimMapping, String> entry : getWrapped().entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                entry.setValue(value != null ? String.valueOf(value) : null);
                return;
            }
        }
    }

    @Override
    public boolean isArray() {

        return true;
    }

    /**
     * Resolves the URI that identifies a given claim mapping (e.g. the local or remote claim URI).
     */
    @FunctionalInterface
    public interface IdMapper {

        String toId(ClaimMapping claimMapping);
    }
}
