package org.wso2.carbon.identity.application.authentication.framework.config.model.graph.js;

import org.wso2.carbon.identity.application.authentication.framework.util.FrameworkConstants;
import org.wso2.carbon.identity.application.common.model.ClaimMapping;

import java.util.Map;
import java.util.function.Consumer;

/**
 * Javascript wrapper for the user's claim map ({@code Map<ClaimMapping, String>}).
 * This provides controlled access to the claims of an authenticated user via provided javascript native syntax.
 * e.g
 * var email = context.subject.claims.local["http://wso2.org/claims/emailaddress"]
 * context.subject.claims.push({local: "...", remote: "...", value: "..."})
 *
 * @see ClaimMapping
 */
public class JsClaimSet extends AbstractJSObjectWrapper<Map<ClaimMapping, String>> {

    public JsClaimSet(Map<ClaimMapping, String> wrapped) {

        super(wrapped);
    }

    @Override
    public Object getMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
                return new JsClaimView(getWrapped(), claimMapping -> claimMapping.getLocalClaim() != null ?
                        claimMapping.getLocalClaim().getClaimUri() : null);
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
                return new JsClaimView(getWrapped(), claimMapping -> claimMapping.getRemoteClaim() != null ?
                        claimMapping.getRemoteClaim().getClaimUri() : null);
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return (Consumer<Object>) this::push;
            default:
                return super.getMember(name);
        }
    }

    @Override
    public boolean hasMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return true;
            default:
                return super.hasMember(name);
        }
    }

    /**
     * Constructs a new {@link ClaimMapping} from the given claim object and inserts it into the wrapped user
     * attributes map. The claim object is expected to expose {@code local}, {@code remote} and {@code value} fields.
     * No entry is added when any of these fields is missing.
     *
     * @param claim javascript claim object.
     */
    public void push(Object claim) {

        if (!(claim instanceof Map)) {
            JsLogger.getInstance().error("Unable to push the claim. The provided claim object is not valid.");
            return;
        }

        Map claimObject = (Map) claim;
        Object local = claimObject.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL);
        Object remote = claimObject.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE);
        Object value = claimObject.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_VALUE);

        if (local == null || remote == null || value == null) {
            JsLogger.getInstance().error("Unable to push the claim. The claim object must contain local, remote and " +
                    "value fields.");
            return;
        }

        ClaimMapping claimMapping = ClaimMapping.build(String.valueOf(local), String.valueOf(remote), null, false);
        getWrapped().put(claimMapping, String.valueOf(value));
    }

    /**
     * @return true if the wrapped user attributes map is empty.
     */
    public boolean isEmpty() {

        return getWrapped().isEmpty();
    }
}
